package cryptosquare

import (
	"strings"
	"unicode"
)

// Encode normalizes the plaintext by removing spaces and punctuation and
// down-casing it, organizes the result into a rectangle as square as
// possible, and returns the rectangle read down the columns left to right,
// with the columns separated by single spaces. Columns that fall short of a
// perfect rectangle are padded with a single trailing space.
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(unicode.ToLower(r))
		}
	}
	s := b.String()
	n := len(s)
	if n == 0 {
		return ""
	}

	c := ceilSqrt(n)
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		var col strings.Builder
		col.Grow(r)
		for i := 0; i < r; i++ {
			if idx := i*c + j; idx < n {
				col.WriteByte(s[idx])
			} else {
				col.WriteByte(' ')
			}
		}
		chunks[j] = col.String()
	}
	return strings.Join(chunks, " ")
}

// ceilSqrt returns the smallest integer c such that c*c >= n.
func ceilSqrt(n int) int {
	c := 0
	for c*c < n {
		c++
	}
	return c
}

